  margin-right: 8px;
}
.tag-post-count {
  font-size: 1.1rem;
  color: var(--gray-600);
  margin-top: 8px;
}

.popular-tags-section { padding: 32px 0 0; }
.popular-tags-scroll {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 24px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}
.popular-tags-scroll::-webkit-scrollbar { height: 4px; }
.popular-tags-scroll::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 4px; }
.popular-tag-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 18px;
  background: var(--gray-100);
  border: 1px solid var(--gray-200);
  border-radius: 24px;
  white-space: nowrap;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: background 0.2s;
  text-decoration: none;
  flex-shrink: 0;
}
.popular-tag-chip:hover {
  background: var(--gray-200);
  text-decoration: none;
}
.popular-tag-chip .chip-count {
  color: var(--gray-500);
  font-size: 0.8rem;
  font-weight: 400;
}

/* --- Footer --- */
.site-footer {
  background: var(--navy);
  color: var(--gray-300);
  padding: 48px 0 32px;
  margin-top: 0;
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.footer-mission {
  font-size: 0.95rem;
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 720px;
}
.footer-trending h4 {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--white);
  margin-bottom: 12px;
}
.footer-trending-links {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin-bottom: 32px;
}
.footer-trending-links a {
  color: var(--gray-400);
  font-size: 0.9rem;
  line-height: 2;
}
.footer-trending-links a:hover { color: var(--white); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.footer-links a {
  color: var(--gray-400);
  font-size: 0.85rem;
}
.footer-links a:hover { color: var(--white); }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card { grid-template-columns: 1fr; }
  .featured-card-body { padding: 24px; }
  .featured-card-image { min-height: 220px; }
  .curriculum-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }
  .article-grid { grid-template-columns: 1fr; }
  .section-heading { font-size: 1.25rem; }
  .featured-card-title { font-size: 1.3rem; }
  .donate-hero h1 { font-size: 1.75rem; }
  .donate-hero p { font-size: 1rem; }
  .curriculum-grid { grid-template-columns: 1fr; }
  .achievements-grid { grid-template-columns: repeat(2, 1fr); }
  .tag-header h1 { font-size: 1.5rem; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .header-inner { padding: 0 16px; }
  .donation-amounts { gap: 8px; }
  .donation-amount-btn { padding: 12px 20px; font-size: 1rem; min-width: 64px; }
  .achievements-grid { grid-template-columns: 1fr; }
}
